/**
 * @summary Activate emergency lock — suspends all non-chairman users and kills their sessions
 */
export const ActivateEmergencyLockResponse = zod.object({
  "suspended": zod.number(),
  "sessionTerminated": zod.number(),
  "message": zod.string()
})


/**
 * @summary Lift emergency lock — reactivates only users suspended by the lock
 */
export const LiftEmergencyLockResponse = zod.object({
  "reactivated": zod.number(),
  "message": zod.string()
})
